                        description: _t("Failed to ban user"),
                    });
                },
            )
            .finally(() => {
                stopUpdating();
            });
    };

    let label = room.isSpaceRoom() ? _t("Ban from space") : _t("Ban from room");
    if (isBanned) {
        label = room.isSpaceRoom() ? _t("Unban from space") : _t("Unban from room");
    }

